#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
cat > apps/world/tests/browser/recast-crowd-worker-benchmark.mjs <<'P0B_RUNNER'
import assert from 'node:assert/strict';
import {createServer} from 'node:http';import {readFile} from 'node:fs/promises';import {resolve,extname} from 'node:path';import {fileURLToPath} from 'node:url';
import {buildCampusArtifact} from '../recast-runtime/build-artifact.mjs';import {prepareCampus} from '../recast-runtime/campus-context.mjs';
const {chromium}=await import('playwright'),root=fileURLToPath(new URL('../../',import.meta.url)),runtime=resolve(root,'tests/recast-runtime/node_modules/@recast-navigation');
const workerSource="let core;\nconst H={x:1.5,y:2,z:1.5},P={radius:.32,height:1.7,maxAcceleration:6,maxSpeed:1.8,collisionQueryRange:1.6,pathOptimizationRange:6,separationWeight:2,updateFlags:31,obstacleAvoidanceType:0,queryFilterType:0};\nconst p3=p=>({x:p.x,y:Number.isFinite(p.y)?p.y:0,z:p.z}),d=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);\nconst pct=(v,q)=>{const s=[...v].sort((a,b)=>a-b);return s[Math.min(s.length-1,Math.floor((s.length-1)*q))]??0};\nfunction overlaps(ps,t=P.radius*1.9){let n=0;for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++)if(d(ps[i],ps[j])<t)n++;return n}\nfunction snap(c,p){const r=c.navMeshQuery.findNearestPoly(p3(p),{halfExtents:H});if(!r.success||!r.nearestRef||!r.nearestPoint)throw Error('INHA_NATIVE_P0B_SNAP_FAILED');return r.nearestPoint}\nfunction tier(nav,pairs,count,steps,dt){const started=performance.now(),crowd=new core.Crowd(nav,{maxAgents:count,maxAgentRadius:P.radius}),items=[];let accepted=0;try{for(let i=0;i<count;i++){const pair=pairs[i%pairs.length],start=snap(crowd,pair.from),target=snap(crowd,pair.to),agent=crowd.addAgent(start,{...P,userData:i});if(agent.agentIndex<0)throw Error('INHA_NATIVE_P0B_ADD_AGENT_FAILED');if(agent.requestMoveTarget(target))accepted++;items.push({agent,start,target})}const setupMs=performance.now()-started,frames=[];for(let i=0;i<steps;i++){const at=performance.now();crowd.update(dt);frames.push(performance.now()-at)}const positions=items.map(x=>x.agent.position());return{agents:count,steps,simulatedSeconds:steps*dt,activeAgents:crowd.getActiveAgentCount(),acceptedTargets:accepted,invalidAgents:items.filter(x=>x.agent.state()===0).length,setupMs,updateMs:frames.reduce((a,b)=>a+b,0),meanFrameMs:frames.reduce((a,b)=>a+b,0)/frames.length,p95FrameMs:pct(frames,.95),maxFrameMs:Math.max(...frames),overlapPairs:overlaps(positions),meanDistanceMoved:items.reduce((s,x)=>s+d(x.start,x.agent.position()),0)/items.length,meanRemainingTargetDistance:items.reduce((s,x)=>s+d(x.agent.position(),x.target),0)/items.length}}finally{crowd.destroy()}}\nself.onmessage=async e=>{if(e.data?.type!=='RUN')return;const started=performance.now();let nav;try{const{coreUrl,binaryUrl,pairs,tiers=[48,100,200],steps=180,dt=1/60}=e.data;core??=await import(coreUrl);await core.init();if(!pairs?.length)throw Error('INHA_NATIVE_P0B_NO_MOVEMENT_PAIRS');const res=await fetch(binaryUrl,{cache:'no-store'});if(!res.ok)throw Error('INHA_NATIVE_P0B_NAVMESH_UNAVAILABLE');nav=core.importNavMesh(new Uint8Array(await res.arrayBuffer()))?.navMesh;if(!nav)throw Error('INHA_NATIVE_P0B_NAVMESH_IMPORT_FAILED');self.postMessage({type:'RESULT',result:{schema:'inha.native-p0b.browser-worker/1',authorityEffect:'NONE',productionCutover:false,benchmarkOnly:true,packageVersion:'0.43.1',movementPairCount:pairs.length,workerElapsedMs:performance.now()-started,agentParameters:{...P},results:tiers.map(n=>tier(nav,pairs,n,steps,dt))}})}catch(err){self.postMessage({type:'ERROR',message:err?.message??String(err),stack:err?.stack??null})}finally{try{nav?.destroy?.()}catch{}}};";
function movementPairs({roster,legacyNavigator}){const dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z),pairs=[];for(const[npcId,m]of roster)for(let leg=0;leg<m.schedule.length;leg++){const e=m.schedule[leg],p=m.schedule[(leg+m.schedule.length-1)%m.schedule.length];if(e.remote||p.remote)continue;const from=m.destinations[p.destination]?.position,to=m.destinations[e.destination]?.position;if(!from||!to||dist(from,to)<.5)continue;const route=legacyNavigator.networkRoute(from,to)??legacyNavigator.route(from,to);if(route?.length)pairs.push({npcId,leg,from:{...from},to:{...to}})}return pairs}
const build=await buildCampusArtifact(),context=await prepareCampus(),pairs=movementPairs(context),binaryUrl=`/recast-data/${build.manifest.binarySha256}.bin`;assert.equal(pairs.length,141);
const server=createServer(async(req,res)=>{try{const path=new URL(req.url,'http://localhost').pathname;if(path==='/__benchmark.html'){res.writeHead(200,{'Content-Type':'text/html','Cache-Control':'no-store'});res.end('<!doctype html><title>P0-B</title>benchmark');return}const file=path.startsWith('/__recast/')?resolve(runtime,path.slice('/__recast/'.length).replace(/^(core|wasm)\//,'$1/dist/')):resolve(root,'.'+path);if(!file.startsWith(root)||file.includes('\0'))throw Error('Invalid path');let body=await readFile(file);if(path.startsWith('/__recast/')&&/\.(mjs|js)$/.test(path)){body=body.toString();for(const[from,to]of [["'@recast-navigation/core'","'/__recast/core/index.mjs'"],['"@recast-navigation/core"','"/__recast/core/index.mjs"'],["'@recast-navigation/wasm'","'/__recast/wasm/recast-navigation.wasm-compat.js'"],['"@recast-navigation/wasm"','"/__recast/wasm/recast-navigation.wasm-compat.js"']])body=body.replaceAll(from,to)}const types={'.html':'text/html','.json':'application/json','.bin':'application/octet-stream','.wasm':'application/wasm'};res.writeHead(200,{'Content-Type':types[extname(file)]??'application/javascript','Cache-Control':'no-store','Access-Control-Allow-Origin':'*'});res.end(body)}catch(err){res.writeHead(404,{'Access-Control-Allow-Origin':'*'});res.end(String(err?.message??err))}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=`http://127.0.0.1:${server.address().port}`;let browser;
try{browser=await chromium.launch({headless:true});const profiles=[{name:'desktop',context:{viewport:{width:1280,height:800}},performanceRepresentative:true},{name:'mobile-emulation',context:{viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:2},performanceRepresentative:false}],observed={};
for(const profile of profiles){const ctx=await browser.newContext(profile.context);await ctx.addInitScript(()=>{const s=window.__p0b={frames:0,maxFrameGapMs:0,longTasks:[],intervalTicks:0,maxIntervalGapMs:0};let pf;const frame=n=>{if(pf!==undefined)s.maxFrameGapMs=Math.max(s.maxFrameGapMs,n-pf);pf=n;s.frames++;requestAnimationFrame(frame)};requestAnimationFrame(frame);let pt=performance.now();setInterval(()=>{const n=performance.now();s.maxIntervalGapMs=Math.max(s.maxIntervalGapMs,n-pt);pt=n;s.intervalTicks++},16);try{new PerformanceObserver(l=>s.longTasks.push(...l.getEntries().map(e=>e.duration))).observe({type:'longtask',buffered:true})}catch{}});const page=await ctx.newPage(),errors=[],failed=[];page.on('pageerror',e=>errors.push(e.message));page.on('requestfailed',r=>failed.push({url:r.url(),error:r.failure()?.errorText}));await page.goto(origin+'/__benchmark.html');const started=performance.now();const result=await page.evaluate(({binaryUrl,pairs,workerSource,coreUrl})=>new Promise((ok,bad)=>{const blobUrl=URL.createObjectURL(new Blob([workerSource],{type:'text/javascript'})),w=new Worker(blobUrl,{type:'module'}),finish=()=>{w.terminate();URL.revokeObjectURL(blobUrl)},timer=setTimeout(()=>{finish();bad(Error('INHA_NATIVE_P0B_BROWSER_TIMEOUT'))},120000);w.onmessage=e=>{if(e.data?.type==='RESULT'){clearTimeout(timer);const v=e.data.result;finish();ok(v)}else if(e.data?.type==='ERROR'){clearTimeout(timer);const msg=e.data.message+'\n'+(e.data.stack??'');finish();bad(Error(msg))}};w.onerror=e=>{clearTimeout(timer);const msg=(e.message||'INHA_NATIVE_P0B_WORKER_ERROR')+' @ '+e.filename+':'+e.lineno+':'+e.colno;finish();bad(Error(msg))};w.postMessage({type:'RUN',coreUrl,binaryUrl,pairs,tiers:[48,100,200],steps:180,dt:1/60})}),{binaryUrl:origin+binaryUrl,pairs,workerSource,coreUrl:origin+'/__recast/core/index.mjs'});const roundTripMs=performance.now()-started;await page.waitForTimeout(100);const responsiveness=await page.evaluate(()=>{const v=window.__p0b;return{...v,longTaskCount:v.longTasks.length,maxLongTaskMs:v.longTasks.length?Math.max(...v.longTasks):0}});if(errors.length||failed.length)console.error('P0B_BROWSER_ERRORS',JSON.stringify({errors,failed}));assert.deepEqual(errors,[]);assert.deepEqual(failed,[]);assert.equal(result.schema,'inha.native-p0b.browser-worker/1');for(const t of result.results){assert.equal(t.activeAgents,t.agents);assert.equal(t.acceptedTargets,t.agents);assert.equal(t.invalidAgents,0);assert.ok(t.meanDistanceMoved>0)}assert.ok(responsiveness.frames>=5);assert.ok(responsiveness.maxFrameGapMs<500);observed[profile.name]={performanceRepresentative:profile.performanceRepresentative,roundTripMs,responsiveness,worker:result};await ctx.close()}
console.log('INHA_NATIVE_P0B_BROWSER_WORKER='+JSON.stringify({schema:'inha.native-p0b.browser-worker-evidence/1',browserVersion:browser.version(),navMeshInitialization:'PREBUILT_IMPORT',navMeshByteLength:build.manifest.byteLength,navMeshTriangles:build.manifest.surface.triangleCount,movementPairCount:pairs.length,observed}))}finally{await browser?.close();await new Promise(r=>server.close(r))}
P0B_RUNNER
npm ci --prefix apps/world/tests/recast-runtime --ignore-scripts
npm ci --prefix apps/world/tests/browser --no-audit --no-fund
(cd apps/world/tests/browser && npx --no-install playwright install --with-deps --only-shell chromium)
node apps/world/tests/browser/recast-crowd-worker-benchmark.mjs
